// Un solo pedido con todos los remitos: así la API gasta una ejecución y no cien.
const facturas = Object.fromEntries($('Leer facturas').all().map(i => [i.json.id_factura, i.json]));
const remitos = $('Leer viajes').all().map(i => i.json).filter(v => v.id_viaje).map(v => ({
  remito: String(v.remito_ctg),
  id_transportista: facturas[v.id_factura]?.id_transportista ?? '',
  fecha_viaje: v.fecha_viaje,
}));
const url = $('Leer parámetros').all().find(i => i.json.parametro === 'url_api_cargas')?.json.valor;
return [{ json: { url, remitos } }];

// Cruza los viajes con la respuesta de la API y decide qué hacer con cada uno.
// Todo lo que es regla se resuelve acá; a la IA solo llegan los casos con cargas parecidas para comparar.
const filas = n => $(n).all().map(i => i.json);
const norm = s => String(s ?? '').replace(/\D/g, '').replace(/^0+/, '');
const P = Object.fromEntries(filas('Leer parámetros').map(p => [p.parametro, p.valor]));
const hoy = P.fecha_ejecucion ? String(P.fecha_ejecucion).slice(0, 10)
                              : $now.setZone('America/Argentina/Buenos_Aires').toISODate();
const diasEntre = (a, b) => Math.round((Date.parse(a) - Date.parse(b)) / 864e5);
const pronto = Number(P.dias_vence_pronto ?? 3);

const facturas = Object.fromEntries(filas('Leer facturas').filter(f => f.id_factura).map(f => [f.id_factura, f]));
const viajes = filas('Leer viajes').filter(v => v.id_viaje);
const libro = Object.fromEntries(filas('Leer libro').filter(c => c.id_caso).map(c => [c.id_caso, c]));
const reclamos = filas('Leer reclamos').filter(r => r.id_reclamo);
const trans = Object.fromEntries(filas('Leer transportistas').filter(t => t.id_transportista).map(t => [t.id_transportista, t]));
const cambios = new Set(filas('Leer cambios').map(c => c.id_control).filter(Boolean));
const api = Object.fromEntries(($json.body?.resultados ?? []).map(r => [r.remito_norm, r]));

const abierto = r => !['Resuelto', 'Cerrado'].includes(r.estado);
const facturaDe = r => r.id_factura || Object.values(facturas).find(f => norm(r.nro_comprobante) && norm(f.nro_comprobante) === norm(r.nro_comprobante))?.id_factura || '';
const reclamoAbierto = idf => reclamos.find(r => abierto(r) && facturaDe(r) === idf);
const usados = new Set(viajes.map(v => norm(v.remito_ctg)));   // remitos que ya tienen su propio viaje
const abiertoLibro = c => c && c.estado !== 'Resuelto';

const out = { nuevos_ia: [], nuevos_regla: [], actualizar_libro: [], cerrar_libro: [], cambios_nuevos: [],
              reclamos_actualizar: [], avisos_prioridad: [], avisos_cierre: [] };
const cuenta = { viajes: viajes.length, ok: 0, cambio_de_transporte: 0, casos: 0, sin_respuesta_api: 0 };
const casosAbiertosPorFactura = {};

for (const v of viajes) {
  const f = facturas[v.id_factura];
  if (!f) continue;
  const rn = norm(v.remito_ctg);
  const r = api[rn];
  const id_caso = `${v.id_factura}-${rn}`;
  if (!r) { cuenta.sin_respuesta_api++; continue; }

  if (r.estado === 'Disponible') {
    const carga = r.cargas[0];
    if (carga.id_transportista === f.id_transportista) cuenta.ok++;
    else {
      cuenta.cambio_de_transporte++;
      if (!cambios.has(id_caso)) out.cambios_nuevos.push({ id_control: id_caso, id_factura: v.id_factura, id_viaje: v.id_viaje,
        remito_ctg: v.remito_ctg, transportista_factura: f.id_transportista, transportista_carga: carga.id_transportista,
        id_carga: carga.id_carga, fecha_viaje: v.fecha_viaje, fecha_vencimiento: f.fecha_vencimiento, fecha_deteccion: hoy,
        estado_control: 'A revisar' });
    }
    // Si había un caso abierto para este viaje, la carga apareció: se cierra solo.
    if (abiertoLibro(libro[id_caso])) out.cerrar_libro.push({ id_caso, estado: 'Resuelto', fecha_cierre: hoy,
      motivo_cierre: 'La carga ya figura disponible en el sistema de cargas.' });
    continue;
  }

  // Desde acá el viaje no tiene una carga disponible única: es un caso de soporte.
  cuenta.casos++;
  casosAbiertosPorFactura[v.id_factura] = (casosAbiertosPorFactura[v.id_factura] ?? 0) + 1;
  const dias = diasEntre(f.fecha_vencimiento, hoy);
  const rec = reclamoAbierto(v.id_factura);
  const prioridad = rec ? '0 · Reclamada' : dias < 0 ? '1 · Vencida' : dias <= pronto ? '2 · Vence pronto' : '3 · Normal';
  const previo = libro[id_caso];
  const avisar = prioridad === '0 · Reclamada' && !(previo?.aviso_prioridad);
  const caso = { id_caso, id_factura: v.id_factura, id_viaje: v.id_viaje, remito_ctg: v.remito_ctg, remito_norm: rn,
    id_transportista: f.id_transportista, fecha_vencimiento: f.fecha_vencimiento, dias_a_vencer: dias, prioridad,
    estado: 'Nuevo', fecha_alta: hoy, es_g4: v.es_g4, estado_carga_api: r.estado, id_reclamo: rec?.id_reclamo ?? '',
    aviso_prioridad: avisar ? hoy : (previo?.aviso_prioridad ?? '') };
  if (avisar) out.avisos_prioridad.push({ ...caso, nro_comprobante: f.nro_comprobante, transportista: f.transportista,
                                          detalle_reclamo: rec.detalle ?? '' });

  if (previo) {
    // Idempotencia: un caso que ya está en el libro solo se toca si cambió la prioridad.
    if (abiertoLibro(previo) && previo.prioridad !== prioridad)
      out.actualizar_libro.push({ id_caso, prioridad, dias_a_vencer: dias, id_reclamo: caso.id_reclamo, aviso_prioridad: caso.aviso_prioridad });
    continue;
  }

  if (r.estado === 'Facturada') {
    const c = r.cargas[0];
    out.nuevos_regla.push({ ...caso, categoria: 'Consulta G4', control_categoria: 'Regla',
      analisis_ia: `La carga ${c.id_carga} ya se usó en la factura ${c.id_factura_que_la_uso}. Bloquear la factura hasta resolver la consulta.` });
  } else if (r.estado === 'Múltiples cargas') {
    out.nuevos_regla.push({ ...caso, categoria: 'Revisión manual', control_categoria: 'Regla',
      analisis_ia: `El remito aparece en ${r.cargas.length} cargas (${r.cargas.map(c => c.id_carga).join(', ')}). Una persona tiene que elegir la correcta.` });
  } else {
    const candidatas = (r.similares ?? []).filter(c => !usados.has(norm(c.remito_ctg)));
    if (candidatas.length === 0)
      out.nuevos_regla.push({ ...caso, categoria: 'Carga no cargada en TMS', control_categoria: 'Regla',
        analisis_ia: 'No hay cargas disponibles del transportista con fecha cercana. Pedir a Logística que dé de alta la carga.' });
    else
      out.nuevos_ia.push({ ...caso, fecha_viaje: v.fecha_viaje, candidatas });
  }
}

// Casos abiertos del libro cuyo viaje ya no está en la base: se dejan como están (los revisa una persona).

// Reclamos: enganchar con su caso, cerrar solos los que ya no tienen casos abiertos, y juntar los que hay que avisar.
const cerrados = new Set(out.cerrar_libro.map(c => c.id_caso));
for (const r of reclamos) {
  const idf = facturaDe(r);
  if (abierto(r)) {
    const casoDeFactura = Object.values(libro).find(c => c.id_factura === idf && abiertoLibro(c) && !cerrados.has(c.id_caso))
                       ?? [...out.nuevos_ia, ...out.nuevos_regla].find(c => c.id_factura === idf);
    if (!r.id_caso && casoDeFactura) out.reclamos_actualizar.push({ id_reclamo: r.id_reclamo, id_factura: idf, id_caso: casoDeFactura.id_caso });
    else if (r.id_caso && !casosAbiertosPorFactura[idf]) {
      const respuesta = 'La carga del viaje ya figura disponible en el sistema y la factura sigue su curso normal de pago.';
      out.reclamos_actualizar.push({ id_reclamo: r.id_reclamo, estado: 'Resuelto', respuesta_analista: respuesta, fecha_cierre: hoy });
      Object.assign(r, { estado: 'Resuelto', respuesta_analista: respuesta, fecha_cierre: hoy });
    }
  }
  if (r.estado === 'Resuelto' && String(r.respuesta_analista ?? '').trim() && !r.aviso_enviado) {
    const f = facturas[idf] ?? {};
    out.avisos_cierre.push({ id_reclamo: r.id_reclamo, canal: r.canal || 'WhatsApp', tipo: r.tipo, detalle: r.detalle ?? '',
      nro_comprobante: r.nro_comprobante || f.nro_comprobante || '', estado_pago: f.estado_pago ?? '',
      respuesta_analista: String(r.respuesta_analista).trim(), id_transportista: r.id_transportista,
      razon_social: f.transportista || trans[r.id_transportista]?.razon_social || '', email_contacto: trans[r.id_transportista]?.email_contacto ?? '', fecha_alta: String(r.fecha_alta ?? '').slice(0, 10) });
  }
}

const resumen = { fecha_ejecucion: hoy, ...cuenta, casos_nuevos: out.nuevos_ia.length + out.nuevos_regla.length,
  a_clasificar_con_ia: out.nuevos_ia.length, prioridad_cambiada: out.actualizar_libro.length, casos_cerrados: out.cerrar_libro.length,
  cambios_nuevos: out.cambios_nuevos.length, reclamos_actualizados: out.reclamos_actualizar.length,
  avisos_prioridad: out.avisos_prioridad.length, avisos_de_cierre: out.avisos_cierre.length };
return [{ json: { ...out, resumen } }];

