// Lee la respuesta de la IA y la controla contra los datos antes de escribir en el libro.
// Contrato: la IA devuelve categoria, id_carga y analisis. Este nodo agrega control_categoria.
const caso = $('Un caso por vez (IA)').item.json;
const texto = String($json.text ?? '');
let r = null;
try { r = JSON.parse(texto.replace(/```json|```/g, '').trim()); } catch (e) { r = null; }

const categorias = ['Posible remito mal cargado', 'Carga no cargada en TMS', 'Revisión manual'];
let categoria = r && categorias.includes(r.categoria) ? r.categoria : null;
let control = categoria ? 'OK' : 'Respuesta inválida';
const elegida = caso.candidatas.find(c => c.id_carga === String(r?.id_carga ?? '').trim());

// Control 1: si dice "mal cargado", la carga tiene que estar entre las candidatas.
if (categoria === 'Posible remito mal cargado' && !elegida) { categoria = null; control = 'Nombró una carga que no estaba en la lista'; }

// Control 2: la distancia entre los números se vuelve a medir acá (cuántas ediciones separan los dos remitos).
const dist = (a, b) => {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i, ...Array(b.length).fill(0)]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++) {
    d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1);
  }
  return d[a.length][b.length];
};
const norm = s => String(s ?? '').replace(/\D/g, '').replace(/^0+/, '');
if (categoria === 'Posible remito mal cargado' && dist(caso.remito_norm, norm(elegida.remito_ctg)) > 2) {
  categoria = null; control = 'Eligió una carga que difiere en más de dos dígitos';
}
// Control 3: si la IA no eligió ninguna, pero hay exactamente una candidata a 1 o 2 dígitos, la IA pudo pasarla por alto.
const cercanas = caso.candidatas.filter(c => dist(caso.remito_norm, norm(c.remito_ctg)) <= 2);
if (categoria && categoria !== 'Posible remito mal cargado' && cercanas.length === 1) {
  categoria = null; control = `La IA no vio la carga ${cercanas[0].id_carga}, que difiere en 1 o 2 dígitos`;
}
if (!categoria) categoria = 'Revisión manual';

return { json: { ...caso, categoria, control_categoria: control,
  analisis_ia: r?.analisis ? String(r.analisis).slice(0, 300) + (elegida && categoria !== 'Revisión manual' ? ` (carga ${elegida.id_carga})` : '')
                           : 'La IA no devolvió una respuesta válida: ' + texto.slice(0, 150) } };

// Deja solo las columnas del Libro_de_casos (lo demás era contexto para decidir).
const cols = ['id_caso', 'id_factura', 'id_viaje', 'remito_ctg', 'remito_norm', 'id_transportista', 'fecha_vencimiento',
  'dias_a_vencer', 'prioridad', 'estado', 'fecha_alta', 'es_g4', 'estado_carga_api', 'categoria', 'analisis_ia',
  'control_categoria', 'id_reclamo', 'aviso_prioridad', 'fecha_cierre', 'motivo_cierre'];
return $input.all().map(i => ({ json: Object.fromEntries(cols.map(c => [c, i.json[c] ?? ''])) }));

// Un solo mail al analista con todos los casos que pasaron a prioridad máxima en esta ejecución.
const casos = $json.avisos_prioridad ?? [];
if (casos.length === 0) return [];
const filas = casos.map(c => `<tr><td>${c.id_caso}</td><td>${c.nro_comprobante}</td><td>${c.transportista}</td><td>${c.id_reclamo}</td><td>${c.dias_a_vencer}</td><td>${c.estado_carga_api}</td><td>${c.detalle_reclamo}</td></tr>`).join('');
return [{ json: {
  asunto: `[Soporte] ${casos.length} caso(s) con reclamo del transportista: prioridad máxima`,
  html: `<div style="font-family:Arial,sans-serif;font-size:14px"><p>Estos casos tienen un reclamo abierto del transportista y pasaron a prioridad <b>0 · Reclamada</b>:</p>
<table cellpadding="6" border="1" style="border-collapse:collapse"><tr style="background:#f3f3f3"><th>Caso</th><th>Comprobante</th><th>Transportista</th><th>Reclamo</th><th>Días a vencer</th><th>Carga</th><th>Lo que dijo el transportista</th></tr>${filas}</table>
<p>Cuando lo resuelvas, escribí la respuesta en la hoja Reclamos (columna respuesta_analista) y poné el estado en Resuelto. El aviso al transportista sale solo.</p></div>` } }];

