// Controla el mail que redactó la IA antes de mandarlo. Si algo no cierra, sale una plantilla fija.
// Contrato: la IA devuelve solo el texto. Este nodo agrega asunto, cuerpo_html, control_respuesta y para.
const r = $('Un reclamo por vez').item.json;
const P = Object.fromEntries($('Leer parámetros').all().map(i => [i.json.parametro, i.json.valor]));
const texto = String($json.text ?? '').trim();
const fuente = [r.respuesta_analista, r.nro_comprobante, r.id_reclamo, r.fecha_alta, r.detalle, r.razon_social].join(' ');

const problemas = [];
const palabras = texto.split(/\s+/).filter(Boolean).length;
if (palabras < 30 || palabras > 200) problemas.push(`largo fuera de rango (${palabras} palabras)`);
if (/\b(T|TMS|F|V)-\d+/.test(texto)) problemas.push('menciona códigos internos');
if (!texto.includes(r.id_reclamo)) problemas.push('no nombra el reclamo');
// Fechas y montos: todo número de 4 o más cifras del mail tiene que estar en los datos de entrada.
const numeros = texto.match(/\d[\d.,\/-]{3,}\d/g) ?? [];
const inventados = numeros.filter(n => !fuente.replace(/\D/g, ' ').includes(n.replace(/\D/g, '')) && !fuente.includes(n));
if (inventados.length) problemas.push('números que no están en los datos: ' + inventados.join(', '));

const plantilla = `Estimados ${r.razon_social}:\n\nLe informamos que el reclamo ${r.id_reclamo}, referido al comprobante ${r.nro_comprobante}, fue resuelto.\n\nResolución: ${r.respuesta_analista}\n\nSi tiene alguna duda, puede responder este mail o escribirnos por WhatsApp.`;
const cuerpo = problemas.length ? plantilla : texto;
const firma = '\n\nSaludos cordiales,\nAtención al transportista';
const html = (cuerpo + firma).split(/\n{2,}/).map(p => `<p>${p.replace(/\n/g, '<br>')}</p>`).join('');

// En modo prueba todos los mails van a la casilla de prueba (parámetro mail_transportista_prueba).
const prueba = P.mail_transportista_prueba && !String(P.mail_transportista_prueba).startsWith('TU_');
return { json: { ...r, para: prueba ? P.mail_transportista_prueba : r.email_contacto,
  asunto: `Reclamo ${r.id_reclamo} resuelto · comprobante ${r.nro_comprobante}`, cuerpo_html: html,
  control_respuesta: problemas.length ? 'Plantilla fija: ' + problemas.join('; ') : 'OK' } };
